import {Game,CREATURES,DICE,creatureDef,creatureName,UPGRADE_TEXT,NODE_TYPES} from './engine.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy=x=>structuredClone(x);
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
let prefs=read('dread-user3-options',read('dread-user2-options',{tutorial:true,speed:'normal'}));
let seen=read('dread-user3-seen',{});
function save(){try{localStorage.setItem('dread-user3-options',JSON.stringify(prefs));localStorage.setItem('dread-user3-seen',JSON.stringify(seen));}catch{}}
let game=null,onTitle=true,selectedSeed=31001,selectedNode=null,mapAct=null,hoverDie=null,selection=null;
let recoveryDraft={mode:null,alloc:{},entityId:null},rewardIndex=null,rewardSlot=null,eventMode=null,eventTarget=null;
let modal=null,queue=[],busy=false,animationState=null,animationEvent=null,previewOpen=false,renderedScene=null;
let pinned=null,tipTimer=null,tipClose=null,targetTimer=null,targetFloor=null;
let dragging=null,lastPointerType='mouse',animationRoute=null,animationStep=0,printingCreature=null;
let expansion={position:0,slot:0,face:0,anxiety:0,fear:0};
const combatPhases=['roll','choose','prepare'];
const nodeNames={normal:'일반 손님 전투',elite:'엘리트 전투',boss:'보스 전투',shop:'상점',recovery:'회복',discovery:'주사위 발견',event:'이벤트'};
const nodeIcons={normal:'♙',elite:'♜',boss:'♛',shop:'▤',recovery:'✚',discovery:'⚄',event:'✉'};
const glossary={
 '통과':'이동의 중간 방문입니다. 그 방문에서는 도착 효과가 함께 발동하지 않습니다.',
 '도착':'이동의 마지막 방문입니다. 도착층의 통과 효과는 함께 발동하지 않습니다.',
 '불안':'손님마다 0~9입니다. 자연 감소하지 않으며 수확·수리에 소비하거나 손님 종료 때 정리됩니다.',
 '수확':'해당 효과의 상한까지 실제 불안을 소비해 공포로 전환합니다. 앞선 공급과 선택 효과도 이번 경로 계산에 포함됩니다.',
 '보호':'개별 타격 순서대로 공략도를 흡수합니다. 같은 대상에 합산되며 손님 공격 뒤 또는 종료 때 남은 양은 사라집니다.',
 '충전':'방화문의 남은 사용을 1 늘립니다. 최대 2회이며 도착으로 얻은 충전은 다음 턴부터 사용합니다.',
 '심장마비':'한 번의 공포 효과가 한계에 닿으면 심장 하나를 제거하고 공포를 0으로 만듭니다. 초과량은 버리며 심장이 남으면 반격합니다.',
 '공략도':'괴이가 받은 공격입니다. 한계 12에 닿으면 파훼 토큰 하나를 잃고 0이 됩니다. 한 타격의 초과량은 버립니다.',
 '파훼 토큰':'괴이의 남은 내구입니다. 0이면 영구 파괴됩니다. 전투와 막을 넘어 이월하며 회복 노드에서 선택해야 회복됩니다.',
 '영혼':'구매 잔액입니다. 처치와 명시된 이벤트로 얻으며, 상점의 괴이·층 구매와 이벤트에 씁니다. 손님 공포와 별개입니다.',
 '강화':'생존 개체 하나의 정해진 효과를 한 번 바꿉니다. 이름에 +가 붙습니다. 현재·최대 파훼 토큰과 현재 사용 잔량은 늘지 않습니다.'
};
const tutorial={
 adventure:['갈림길을 고르는 모험','각 막에서 8개 노드를 방문합니다. 연결된 다음 노드를 살펴본 뒤 방문을 확정하세요. 7번째 회복을 거쳐 8번째 보스로 향합니다.'],
 souls:['공포와 영혼은 다릅니다','손님에게 쌓는 공포는 심장을 제거합니다. 처치해서 얻은 영혼은 상점과 이벤트에서 쓰는 구매 잔액입니다.'],
 tokens:['남은 파훼 토큰은 이월됩니다','다음 전투 준비에서는 공략도와 직접 사용 잔량만 복구됩니다. 잃은 파훼 토큰은 회복 노드에서 회복을 선택해야 채워집니다.'],
 placement:['호텔을 자유롭게 배치하세요','보관 카드를 층으로 끌거나 배치하기를 누른 뒤 층을 선택하세요. 층끼리 교환하거나 보관함으로 회수해도 토큰과 강화는 유지됩니다.'],
 shop:['상점에 머물며 구매하세요','괴이 상품 8개와 층 증설은 같은 영혼 잔액을 사용합니다. 구매 없이 떠날 수도 있으며 상품 구매나 증설만으로 방문이 끝나지 않습니다.'],
 recovery:['회복 또는 강화 중 하나','회복은 호텔 전체에 토큰 총 2개를 배분합니다. 강화는 미강화 생존 괴이 하나의 효과를 바꿉니다. 보관 중인 괴이도 대상이며 둘 중 하나만 받을 수 있습니다.'],
 reward:['세 괴이 중 하나를 발견했습니다','서로 다른 기본 괴이 세 종류 중 하나를 무료로 획득하세요. 새 개체는 보관함으로 들어가며 기존 개체의 손상이나 강화를 합치지 않습니다.'],
 discovery:['새 주사위 하나를 비교하세요','새 주사위를 받으면 현재 세 개 중 한 자리를 교체합니다. 발견과 엘리트 보상은 무료로 건너뛸 수 있으며 보스는 주사위를 주지 않습니다.'],
 event:['사건의 결과를 보고 선택하세요','공개된 비용과 결과 중 하나를 확정합니다. 대상을 살펴보거나 비교를 취소하는 동안에는 영혼과 소유 상태가 바뀌지 않습니다.'],
 combat:['공포와 불안, 두 가지 흐름','중간층은 통과 효과, 마지막 층은 도착 효과를 발동합니다. 불안을 공급하고 수확해 공포를 올리세요. 공포 한계에 닿으면 심장 하나를 제거하고 공포를 0으로 만듭니다. 초과 공포는 버리며 심장이 남으면 반격합니다.'],
 durability:['괴이의 파훼와 영구 파괴','받은 공격은 괴이의 공략도가 됩니다. 한 타격으로 12에 닿으면 파훼 토큰 하나를 잃고 공략도는 0이 됩니다. 토큰이 0이면 즉시 빈층으로 바뀌며, 배치 괴이가 전부 파괴되면 보관 괴이가 있어도 패배합니다.'],
 inactivity:['아무 일도 일어나지 않는 밤','실제 불안 증가·공포 부여·적법한 직접 사용이 없는 턴이 처음 3번, 이후 2번씩 이어지면 무작위 배치 괴이가 보호를 무시하는 공략도 12를 받습니다. 유효한 활동으로 유예를 3턴으로 돌릴 수 있습니다.'],
 dice:['세 주사위 중 하나','주사위를 살펴보면 경로·공포·심장·받을 공격이 함께 예고됩니다. 주사위 확정과 이동 실행은 별도 조작입니다.'],
 active:['노란 테두리의 층을 눌러 사용','눈 확정 뒤 사용할 수 있는 괴이 층이 노란 테두리로 표시됩니다. 보호·수리는 호텔 본체의 층을 검토한 뒤 확정하세요.'],
 target:['호텔의 대상 층을 고르세요','전체 층의 위치는 고정됩니다. 유효한 층에 마우스나 키보드 초점을 두어 결과를 살펴보고 클릭이나 확정 키로 사용하세요. 검토에는 비용이 들지 않으며, 터치는 같은 층을 두 번 눌러 확정합니다.'],
 escape:['출구를 실제로 지나야 합니다','이동 전에 빈층에 출구를 한 번 설치할 수 있습니다. 접촉하면 일반·엘리트는 무보상 탈출로 끝나며 어느 막이든 보스 탈출은 패배입니다.'],
 upgrade:['강화는 이 개체에만 적용됩니다','강화한 괴이는 이름에 +가 붙습니다. 토큰과 현재 사용 잔량은 그대로이며 파괴되면 강화도 함께 사라집니다.'],
 final:['최종 보스 전투 승리','마지막 괴이를 선택하면 최종 보유 목록에 추가되고 승리 결과로 갑니다. 다음 판에는 자산이 이월되지 않습니다.']
};
function teach(...keys){if(!prefs.tutorial)return;for(const key of keys)if(tutorial[key]&&!seen[key]&&!queue.includes(key))queue.push(key);showNextTutorial();}
function showNextTutorial(){if(!modal&&!busy&&queue.length){modal={type:'tutorial',key:queue.shift()};renderModal();}}
function state(){return animationState||game?.s;}
function node(s=state()){return s?.maps[s.act-1].find(n=>n.id===s.currentNode)||null;}
function entity(id,s=state()){return s?.entities.find(e=>e.id===id);}
function at(f,s=state()){return s?.entities.find(e=>e.floor===f&&e.p>0)||null;}
function name(e){return creatureName(e);}
function def(e){return creatureDef(e);}
function button(text,action,extra='',disabled=false){return `<button class="button ${extra}" data-action="${esc(action)}" ${disabled||busy?'disabled':''}>${text}</button>`;}
function shape(type){return `<span class="shape" data-type="${type}" aria-hidden="true"></span>`;}
function term(key){return `<button class="term" data-action="term:${key}" title="${esc(glossary[key])}">${key}</button>`;}
function keywords(text){return esc(text).replace(/파훼 토큰|심장마비|공략도|불안|수확|보호|충전|통과|도착|영혼|강화/g,key=>term(key));}
function editable(){return !!game&&!busy&&!['anomaly_reward','die_reward','discovery','won','lost'].includes(game.s.phase)&&['map','management','shop','recovery','event'].includes(game.s.phase)&&!recoveryDraft.mode&&!eventMode;}
function newDrafts(){selectedNode=null;hoverDie=null;selection=null;recoveryDraft={mode:null,alloc:{},entityId:null};rewardIndex=null;rewardSlot=null;eventMode=null;eventTarget=null;previewOpen=false;clearTarget(false);}
function effects(e){const d=def(e),rows=[['통과',d.passText],['도착',d.arrivalText],['직접 사용',d.activeText]];const content=rs=>rs.map(([k,t])=>`<div><span class="effect-label">${glossary[k]?term(k):k}</span><p>${keywords(t||'효과 없음')}</p></div>`).join('');return `<div class="effect-list">${content(rows.filter(([,t])=>t&&t!=='효과 없음'))}</div><details class="card-details"><summary>모든 효과 상세</summary><div class="effect-list">${content(rows)}</div></details>`;}
function card(e,footer='',extra=''){const type=typeof e==='string'?e:e.type,d=def(e),owned=typeof e==='object',v=state()?.visitor;let current='';if(owned&&v&&combatPhases.includes(state().phase)){const a=v.a,text=type==='Q'?`불안 ${Math.min(d.harvestCap,a)} 수확 → 공포 ${Math.min(d.harvestCap,a)*4}`:type==='U'?`통과 +${Math.min(d.passAnxiety,9-a)} · 도착 +${Math.min(4,9-a)}`:type==='E'?`통과 +${Math.min(a,9-a)} · 도착 +${Math.min(d.arrivalAnxiety,9-a)}`:'';if(text)current=`<p class="card-current"><small>지금 불안만으로 계산</small><br>${text}</p>`;}
return `<article class="card creature-card ${extra}" data-type="${type}"><div class="card-art">${corridorArt(type,true)}</div><div class="card-top">${shape(type)}<span>${esc(d.role)}</span>${owned&&e.upgraded?'<span class="badge">강화됨</span>':''}</div><h3>${esc(d.name)}</h3>${effects(e)}<div class="card-stats">${term('공략도')} ${owned?e.c:0}/12 · ${term('파훼 토큰')} ${owned?e.p:d.maxP}/${d.maxP}${d.maxUses?`<br>비용: 사용 1회 · 남은 사용 ${owned?e.uses:d.maxUses}/${d.maxUses}회<br><small>다음 전투 준비 최초 진입 시 ${d.maxUses}회</small>`:''}${type==='R'?'<br>비용: 불안 2 · 공략도 있는 대상 · 별도 횟수 제한 없음':''}${owned&&e.shield?`<br>이번 턴 보호 ${e.shield}`:''}</div>${current}<p class="card-location muted">${owned?`${e.floor?e.floor+'층':'보관 중'} · 개체 ${e.id.replace('e','')}`:`미강화 새 개체 · 같은 종류 ${game?.s.entities.filter(x=>x.type===type).length||0}개 보유`}</p>${footer}</article>`;}
function diceFaces(type){return `<span class="dice-faces">${DICE[type].faces.map(v=>`<span class="face ${type==='anxiety'&&v===3?'effect':''}">${v}${type==='anxiety'&&v===3?'<sup>+1</sup>':''}</span>`).join('')}</span>`;}
function equipment(){return `<div class="equipment-list">${state().equipped.map((type,i)=>`<div class="equipment-die"><strong>${i+1}. ${DICE[type].name}</strong>${diceFaces(type)}<small>${esc(DICE[type].effectText)}</small></div>`).join('')}</div>`;}
function seedSelector(){return `<label class="seed-selector">시작 난수 번호 <select data-setting="seed">${[31001,31002,31003].map(n=>`<option value="${n}" ${selectedSeed===n?'selected':''}>${n}</option>`).join('')}</select></label>`;}
function header(){const s=state(),n=node(s);return `<header class="topbar"><a href="#" data-action="title" class="brand"><span class="brand-mark">◈</span><span>DREAD TO DEAD<small>FEARS GO ROUND · USER 3</small></span></a><div class="journey-status"><strong>${s.act}막 / 3</strong><span>방문 완료 ${s.completed[s.act-1]} / 8</span><small>${n?`현재 ${n.depth}번째: ${nodeNames[n.kind]}`:'다음 경로 선택'}${combatPhases.includes(s.phase)?` · 손님 ${s.guestIndex+1}/${n?.guests.length||1}`:''}</small></div><div class="resource"><span>◈ 보유 영혼</span><strong>${s.money}</strong></div><nav class="top-actions">${button('지도','map','ghost small')}${button('호텔','hotel','ghost small')}${button('장비','equipment','ghost small')}${button('기록','record','ghost small')}${button('도움말','help','ghost small')}${button('옵션','options','ghost small')}${!s.finalVictory&&!['won','lost'].includes(s.phase)?button('포기','surrenderconfirm','ghost small'):''}</nav></header>`;}
function guestInvitation(g,kind='normal'){return `<article class="invitation"><div class="invitation-crest">◈ GRAND HOTEL ◈</div><span class="eyebrow">${nodeNames[kind]||'손님'}</span><h3>${esc(g.name)} 귀하</h3><p class="invitation-greeting">귀하의 방문을 기다리고 있겠습니다.</p><div class="invitation-stats">공포 한계 <strong>${g.t}</strong> · 심장 <strong>${g.h}개</strong></div><p>공격: ${esc(g.attackText)}</p><p>처치 보상: <strong>영혼 ${g.reward}</strong></p><small>노드 완승 시 괴이 3중 1${kind==='elite'?' · 특수 주사위 1개 기회':''}${kind==='boss'?' · 탈출 시 패배':''}</small></article>`;}
function currentMap(act=mapAct||state().act){return game.s.maps[act-1];}
function mapNodeInfo(n,readonly=false){if(!n)return `<div class="empty-state"><span>↗</span><h2>다음 기회를 고르세요</h2><p>아래 시작점에서 위 보스로 향합니다.<br>연결된 노드를 살펴보고 방문을 확정하세요.</p></div>`;const can=!readonly&&game.s.phase==='map'&&game.availableNodes().some(x=>x.id===n.id);const descriptions={shop:'괴이 상품 8개와 별도 층 증설을 영혼으로 구매합니다. 재고는 방문 후 공개하며 구매 없이 떠날 수 있습니다.',recovery:'호텔 전체 파훼 토큰 총 2개 배분 또는 생존 괴이 1개 강화 중 하나. 무료이며 아무것도 받지 않아도 됩니다.',discovery:'랜덤 특수 주사위 1개를 무료 교체하거나 거절합니다. 영혼 증감은 없으며 종류는 방문 후 공개됩니다.',event:'사건의 비용과 결과를 보고 하나를 선택합니다. 사건과 제시물은 방문 후 공개됩니다.',normal:'손님 세 명을 연속 상대합니다. 전원 처치하면 괴이 3개 중 하나를 무료 획득합니다.',elite:'강한 손님 한 명. 완승하면 영혼 6, 괴이 3중 1, 특수 주사위 1개 기회를 얻습니다.',boss:`반드시 처치해야 진행합니다. ${n.act<3?'괴이 보상 뒤 다음 막으로 갑니다.':'마지막 괴이 보상 뒤 승리합니다.'} 보스 주사위 보상은 없습니다.`};return `<span class="eyebrow">${n.act}막 · ${n.depth}번째 방문</span><h2>${nodeIcons[n.kind]} ${nodeNames[n.kind]}</h2>${n.depth===7?'<span class="badge">보스 전 필수 경유</span>':''}<p>${descriptions[n.kind]}</p>${n.guests?`<div class="node-guests">${n.guests.map((g,i)=>`<details><summary>${i+1}. ${esc(g.name)} · 한계 ${g.t} · 심장 ${g.h}</summary>${guestInvitation(g,n.kind)}</details>`).join('')}</div>`:''}<p class="muted">${n.next.length?`이후 연결: ${n.next.map(id=>{const x=currentMap(n.act).find(q=>q.id===id);return `${x.depth}번째 ${nodeNames[x.kind]}`;}).join(' / ')}`:'이 막의 마지막 방문'}</p><div class="sticky-actions">${button('이 노드 방문','visit','primary',!can)}<small>${readonly?'현재 노드를 마친 뒤 다음 경로를 선택합니다.':can?'방문하면 경로가 잠깁니다.':n.status==='completed'?'이미 완료한 방문입니다.':'연결된 다음 깊이만 방문할 수 있습니다.'}</small></div>`;}
function mapBoard(readonly=false){const act=mapAct||state().act,nodes=currentMap(act),avail=new Set(!readonly&&act===game.s.act?game.availableNodes().map(n=>n.id):[]);const point=n=>({x:100+n.column*200,y:75+(8-n.depth)*110});const lines=nodes.flatMap(n=>n.next.map(id=>{const next=nodes.find(x=>x.id===id),a=point(n),b=point(next),done=n.status==='completed'&&next.status==='completed',active=avail.has(next.id)&&n.status==='completed';return `<path d="M${a.x} ${a.y} L${b.x} ${b.y}" class="${done?'completed':active?'available':''}"/>`;})).join('');return `<section class="map-panel"><div class="map-toolbar"><div><span class="eyebrow">THE JOURNEY</span><h2>${act}막의 여행 기록지</h2></div>${button('현재 경로','mapcurrent','ghost small')}${button('보스 위치','mapboss','ghost small')}</div><nav class="act-strip">${[1,2,3].map(a=>button(`${a}막${a<game.s.act?' · 완료':a===game.s.act?' · 현재':' · 미도달'}`,'mapact:'+a,'ghost small '+(a===act?'selected':''),a>game.s.act)).join('')}</nav><div class="map-scroll"><div class="map-board"><svg class="map-connections" viewBox="0 0 600 980" preserveAspectRatio="none" aria-hidden="true">${lines}<path d="M300 945 L100 845 M300 945 L300 845 M300 945 L500 845" class="start-lines"/></svg>${nodes.map(n=>{const p=point(n),status=avail.has(n.id)?'방문 가능':n.status==='active'?'진행 중':n.status==='completed'?'완료':n.status==='closed'?'닫힌 갈래':'미도달';return `<button class="map-node ${n.status} ${avail.has(n.id)?'available':''} ${selectedNode===n.id?'selected':''}" style="left:${p.x/6}%;top:${p.y}px" data-action="node:${n.id}" data-node="${n.id}" data-kind="${n.kind}" aria-label="${n.depth}번째 ${nodeNames[n.kind]} ${status}"><span class="node-icon">${nodeIcons[n.kind]}</span><strong>${n.depth}. ${nodeNames[n.kind]}</strong><small>${status}</small></button>`;}).join('')}<div class="map-start">◈ 시작점</div></div></div></section>`;}
function mapScreen(readonly=false){const n=currentMap().find(x=>x.id===selectedNode);return `<main class="adventure-layout map-layout">${mapBoard(readonly)}<aside class="node-info node-detail"><section class="selected-node-info">${mapNodeInfo(n,readonly)}</section><section class="hotel-summary"><h3>함께 여행하는 호텔</h3><p>${state().floorCount}층 · 배치 ${state().entities.filter(e=>e.floor).length}개 · 보관 ${state().entities.filter(e=>!e.floor).length}개</p><p>파훼 토큰은 다음 전투에도 이월됩니다.</p>${button('호텔과 보관함 보기','hotel','ghost')}${equipment()}</section></aside></main>`;}

function corridorArt(type,mini=false){return `<div class="corridor ${mini?'mini':''}"><div class="doors">${[1,2,3].map(i=>`<span class="door room-door"><i></i><b>${i}</b></span>`).join('')}</div><span class="lamp wall-lamp"></span><span class="lamp wall-lamp second"></span><span class="corridor-base"></span>${type?`<span class="manifestation" data-type="${type}">${shape(type)}<i></i><i></i><i></i></span>`:''}<span class="elevator-door">⇅</span></div>`;}
function currentPreview(){if(!game||busy||!['choose','prepare'].includes(game.s.phase))return null;if(game.s.phase==='choose'&&hoverDie==null)return null;const actions=selection&&targetFloor!=null&&validTarget(targetFloor)?selection.kind==='escape'?[{kind:'escape',floor:targetFloor}]:['G','R'].includes(selection.kind)?[{kind:'active',entityId:selection.id,targetId:at(targetFloor,game.s).id}]:[]:[];return game.preview(game.s.phase==='choose'?hoverDie:undefined,actions);}
function validTarget(f){const e=at(f,game.s);if(!selection)return false;if(selection.kind==='place')return f>=1&&f<=game.s.floorCount;if(selection.kind==='escape')return !e;if(selection.kind==='G')return !!e;if(selection.kind==='R')return !!e&&e.c>0;return false;}
function threat(p,e,f){const hits=p?.attacks.filter(x=>x.floor===f)||[];if(!hits.length)return '';const powers=hits.map(x=>x.power),final=e&&p.state.entities.find(x=>x.id===e.id),loss=e?e.p-(final?.p||0):0;const txt=powers.every(x=>x===powers[0])?`공략도 ${powers[0]}${powers.length>1?' × '+powers.length:''}`:'공략도 '+powers.join(' → '),risk=e?final?loss?'토큰 −'+loss:'토큰 보존':'파괴 예상':'빈층';return `<button class="floor-threat ${loss?'danger-text':''}" data-action="floorinfo:${f}" title="${esc(txt+' · '+risk)}" aria-label="${f}층 공격 상세 · ${esc(txt+' · '+risk)}">${txt} · ${risk}</button>`;}
function coreEffect(e){const d=def(e);return e.type==='U'?`통과 불안 +${d.passAnxiety} · 도착 +${d.arrivalAnxiety}`:e.type==='Q'?`도착 불안 최대 ${d.harvestCap} → 공포 4배`:e.type==='B'?'도착·직접 사용 공포 +3':e.type==='G'?`도착 충전 · 직접 보호 ${d.shieldPower}`:e.type==='E'?`통과 불안 두 배 · 도착 +${d.arrivalAnxiety}`:`직접 불안 2 → 공략도 최대 −${d.repairPower}`;}
function routeSteps(events,startPosition=0,floorCount=state()?.floorCount||6){const steps=[];let current=null,from=startPosition;for(const event of events||[]){if(event.kind==='move'){current={order:steps.length+1,floor:event.floor,from,arrival:!!event.arrival,kind:event.arrival?'arrival':'pass',wrap:from===floorCount&&event.floor===1,events:[],effects:[],ended:null};steps.push(current);from=event.floor;}else if(current&&['anxiety','harvest','fear','charge','heart','kill','escape'].includes(event.kind)){current.events.push(event);if(event.kind==='anxiety')current.effects.push(event.amount>0?`불안 +${event.amount}`:event.wasted>0?'불안 상한 · 증가 0':'불안 증가 0');if(event.kind==='harvest')current.effects.push(event.amount>0?`불안 −${event.amount}`:'수확 0');if(event.kind==='fear'&&event.amount>0)current.effects.push(`공포 +${event.amount}`);if(event.kind==='charge')current.effects.push(event.amount>0?`방어 횟수 +${event.amount} · 다음 턴 사용`:'충전 상한 · 증가 0');if(event.kind==='heart')current.hearts=(current.hearts||0)+1;if(event.kind==='kill'||event.kind==='escape'){current.ended=event.kind;if(event.kind==='escape')current.kind='escape';}}}for(const step of steps){step.label=`${step.arrival?'도착':'통과'} · ${step.effects.length?step.effects.join(' / '):'효과 없음'}${step.ended==='escape'?' · 탈출 종료':step.ended==='kill'?' · 처치 종료':''}`;step.effectText=step.ended==='escape'?'탈출 · 이후 이동 취소':step.effects.length?step.effects.map(text=>text.replace('방어 횟수','충전').replace('다음 턴 사용','다음 턴')).join(' / '):'효과 없음';}return steps;}
function routeLane(p){const s=state(),height=s.floorCount*46-2,actual=!!animationRoute,steps=actual?animationRoute:routeSteps(p?.events,s.visitor?.pos||0,s.floorCount),y=f=>(s.floorCount-f)*46+22;const labels=steps.map(step=>({...step,y:y(step.floor)})).sort((a,b)=>a.y-b.y||a.order-b.order);for(let i=0;i<labels.length;i++)labels[i].labelY=Math.max(labels[i].y,i?labels[i-1].labelY+34:16);if(labels.length&&labels.at(-1).labelY>height-16){labels.at(-1).labelY=height-16;for(let i=labels.length-2;i>=0;i--)labels[i].labelY=Math.min(labels[i].labelY,labels[i+1].labelY-34);}const positions=new Map(labels.map(step=>[step.order,step.labelY]));return `<aside class="route-lane ${actual?'actual-route':'forecast-route'}" aria-label="${actual?'실제 이동 처리':'이동 경로 예고'}"><div class="route-track"><svg class="route-svg" viewBox="0 0 240 ${height}" preserveAspectRatio="none" aria-hidden="true"><defs><marker id="route-arrowhead" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L8 4L0 8Z"/></marker></defs>${steps.map(step=>{const start=step.from?y(step.from):height+5,end=y(step.floor),x=20+(step.order> s.floorCount?7:0),path=step.wrap?`M${x} ${start} C58 ${start},58 ${end},${x} ${end}`:`M${x} ${start} L${x} ${end+5}`,phase=actual?step.order===animationStep?'current':step.order<animationStep?'done':'pending':'forecast';return `<path class="route-arrow ${step.wrap?'wrap':''} ${step.arrival?'arrival':''} ${phase}" data-route-step="${step.order}" d="${path}" marker-end="url(#route-arrowhead)"/><path class="route-leader ${phase}" d="M${x+5} ${end} L62 ${positions.get(step.order)}"/><circle class="route-point ${phase}" cx="${x}" cy="${end}" r="3"/>`;}).join('')}</svg>${steps.map(step=>`<div class="route-effect-label ${step.arrival?'arrival':''} ${actual?step.order===animationStep?'current':step.order<animationStep?'done':'pending':'forecast'}" style="top:${positions.get(step.order)/height*100}%" data-route-order="${step.order}" data-route-floor="${step.floor}" data-route-kind="${step.kind}" data-route-wrap="${step.wrap}" title="${esc(step.label+(step.hearts?' · 심장 '+step.hearts+'개 제거':''))}"><strong>${step.order} · ${step.floor}층 ${step.ended==='escape'?'탈출':step.arrival?'도착':'통과'}${step.wrap?' ↻':''}</strong><span>${esc(step.effectText)}</span></div>`).join('')}${steps.length?'':'<p class="route-empty">주사위를 검토하면<br>방문 순서와 효과를<br>화살표로 표시합니다.</p>'}</div><p class="route-caption">${actual?'실제 방문을 순서대로 처리 중':steps.length?'경로 예고 · 숫자는 방문 순서':'호텔 전체 고정 표시'}</p></aside>`;}

function hotelFloors(p=null,readonly=false){const s=state(),canEdit=editable()&&!readonly,withRoute=combatPhases.includes(s.phase)&&modal?.type!=='hotel',route=animationRoute||routeSteps(p?.events,s.visitor?.pos||0,s.floorCount),path=route.map(step=>step.floor),targeting=selection&&['G','R','escape'].includes(selection.kind);return `<div class="hotel-board ${withRoute?'with-route':''}" style="--floor-count:${s.floorCount}" aria-label="전체 ${s.floorCount}층 호텔과 지하"><div class="hotel-building"><div class="hotel-floors">${Array.from({length:s.floorCount},(_,i)=>s.floorCount-i).map(f=>{const e=at(f,s),d=e&&def(e),usable=e&&!busy&&!targeting&&modal?.type!=='hotel'&&s.phase==='prepare'&&!game.activeReason(e.id),isTarget=selection&&validTarget(f),current=s.visitor?.pos===f;return `<section class="floor compact-floor ${e?'':'empty'} ${usable?'usable':''} ${path.includes(f)?'transit':''} ${path.at(-1)===f?'arrival':''} ${current?'occupied':''} ${isTarget?'targetable':''} ${targeting&&!isTarget?'target-invalid':''} ${selection&&e&&selection.id===e.id?'selected':''} ${targetFloor===f?'target-preview':''}" data-floor="${f}" ${e?`data-entity="${e.id}" data-type="${e.type}" ${canEdit?`draggable="true" data-drag="${e.id}"`:''}`:''} tabindex="0" role="group" aria-label="${f}층 ${e?esc(name(e)):'빈층'}${usable?' · 직접 사용 가능':''}${targeting?isTarget?' · 대상 가능':' · 대상 불가':''}"><div class="floor-label"><strong>${f}<small>층</small></strong><h3>${e?esc(name(e)):s.escape===f?'탈출구':'빈 객실 복도'}</h3>${e?button('ⓘ','info:'+e.id,'info-button'):button('ⓘ','floorinfo:'+f,'info-button')}</div><div class="corridor-scene">${corridorArt(e?.type)}${current?'<span class="guest-silhouette"><i></i><b></b></span>':''}${s.escape===f?'<span class="exit-sign">EXIT ↗</span>':''}</div><div class="floor-info">${e?`<p class="floor-summary" title="${esc(d.summary)}">${esc(coreEffect(e))}</p><div class="floor-stats"><span>공략도 ${e.c}/12</span><span>파훼 토큰 ${e.p}/${d.maxP}</span>${d.maxUses?`<span>사용 ${e.uses}/${d.maxUses}</span>`:''}${e.shield?`<span>보호 ${e.shield}</span>`:''}</div>`:`<p class="floor-summary">${s.escape===f?'접촉 시 전투 종료':canEdit?'카드를 놓아 배치':'통과·도착 효과 없음'}</p>`}<span class="floor-forecast">${targetFloor===f?'대상 검토 · 아직 미확정':''}</span></div><div class="floor-actions">${canEdit&&e?button('이동','place:'+e.id,'ghost small')+button('보관','store:'+e.id,'ghost small'):usable?`<span class="active-hint">${e.type==='B'?'공포 +3':e.type==='G'?'보호':'수리'}<br>직접 사용</span>`:targeting?`<span class="target-hint">${isTarget?'대상 선택':selection.kind==='R'&&e?'손상 없음':selection.kind==='escape'?'빈층 필요':'대상 불가'}</span>`:''}</div>${threat(p,e,f)}<span class="floor-event">${animationEvent?.floor===f?esc(animationEvent.text):''}</span></section>`;}).join('')}</div><section class="basement-machine machine compact-machine ${printingCreature?'working':''}"><span class="eyebrow">지하 · 직원 전용</span><div class="machine-body"><span class="wrapped-guest"></span><span class="machine-mouth"></span><span class="machine-gears">⚙</span><span class="machine-card" ${printingCreature?`data-type="${printingCreature.type}"`:''}>${printingCreature?shape(printingCreature.type):'◈'}</span></div><p>${printingCreature?esc(name(printingCreature))+' 카드 출력':'괴이 카드 출력 설비'}</p></section></div>${withRoute?routeLane(p):''}</div>`;}

function inventory(readonly=false){const s=state(),canEdit=editable()&&!readonly,items=s.entities.filter(e=>e.floor==null);return `<section class="inventory-dock inventory-panel ${dragging?'drop-ready':''}" data-drop="inventory"><div class="panel-header"><h3>보관함 <small>${items.length}개</small></h3>${canEdit&&selection?.kind==='place'?button('선택 괴이 보관','store:'+selection.id,'ghost small'):''}<small>${canEdit?'카드를 층으로 드래그하거나 배치하기':'현재 읽기 전용'}</small></div><div class="inventory-scroll">${items.length?items.map(e=>`<article class="inventory-card ${e.id===selection?.id?'selected':''}" data-type="${e.type}" data-tooltip-entity="${e.id}" tabindex="0" ${canEdit?`draggable="true" data-drag="${e.id}"`:''}><div class="inventory-art">${corridorArt(e.type,true)}</div><h4>${esc(name(e))}</h4><p>개체 ${e.id.replace('e','')} · 토큰 ${e.p}/${def(e).maxP}</p><small>${esc(def(e).summary)}</small><div>${button('정보','info:'+e.id,'ghost small')}${canEdit?button('배치하기','place:'+e.id,'small'):''}</div></article>`).join(''):'<div class="inventory-empty">보관함이 비어 있습니다.<br>새로 획득한 괴이는 이곳에 카드로 들어옵니다.</div>'}</div></section>`;}
function guestStrip(){const n=node();return n?.guests?`<div class="guest-strip"><span class="eyebrow">이번 영업의 초대 손님</span>${n.guests.map((g,i)=>`<button class="guest-thumb" data-action="guest:${i}" data-guest="${i}"><span class="portrait">♙</span><span>${i+1}. ${esc(g.name)}</span></button>`).join('')}</div>`:'';}
function preparation(){const s=state();return `<div class="panel-heading"><span class="eyebrow">OPENING PREPARATIONS</span><h2>${nodeNames[node().kind]} 준비</h2></div><div class="notice">공략도 0 · 직접 사용 잔량 복구 완료<br><strong>파훼 토큰과 강화는 이월한 현재 상태입니다.</strong></div><p>배치 ${s.entities.filter(e=>e.floor).length}개 · 빈층 ${s.floorCount-s.entities.filter(e=>e.floor).length}개 · 보관 ${s.entities.filter(e=>!e.floor).length}개</p>${equipment()}<div class="invitation-list">${node().guests.map(g=>guestInvitation(g,node().kind)).join('')}</div><div class="sticky-actions">${button('영업 시작','start','primary',!s.entities.some(e=>e.floor))}<small>시작은 추가 복구를 발생시키지 않습니다.</small></div>`;}
function shop(){const s=state(),stock=node().contents.stock,cost=game.expansionCost();return `<div class="panel-heading"><span class="eyebrow">THE CURIO SHOP</span><h2>괴이와 새 공간</h2><p>괴이 8개 중 품절 ${stock.filter(x=>x.bought).length}개 · 보유 영혼 ${s.money}</p></div><section class="expansion-offer"><div><strong>꼭대기에 빈층 증설</strong><p>${s.floorCount}층${cost!=null?` → ${s.floorCount+1}층 · ${cost}영혼`:' · 최대 층 수'}</p></div>${button('경로 비교','expand','ghost',cost==null)}</section><div class="shop-grid">${stock.map(item=>{const d=def(item.type),missing=Math.max(0,d.price-s.money);return `<article class="shop-item ${item.bought?'sold':''}" data-tooltip-type="${item.type}" tabindex="0"><div class="shop-art">${corridorArt(item.type,true)}</div><h3>${esc(d.name)}</h3><p>영혼 ${d.price} · ${item.bought?'품절':'잔액 '+s.money+' → '+(s.money-d.price)}</p><div>${button('효과 정보','typeinfo:'+item.type,'ghost small')}${button(item.bought?'품절':missing?'영혼 '+missing+' 부족':'구매','buy:'+item.slot,'small primary',item.bought||missing>0)}</div></article>`;}).join('')}</div><div class="sticky-actions">${button('상점 떠나기','leave','primary')}<small>상품 구매와 증설 뒤에도 상점에 머뭅니다.</small></div>`;}
function recovery(){const s=state(),rd=recoveryDraft,used=Object.values(rd.alloc).reduce((a,b)=>a+b,0),canHeal=s.entities.some(e=>e.p<def(e).maxP),canUpgrade=s.entities.some(e=>!e.upgraded);let body=`<div class="panel-heading"><span class="eyebrow">REST & REPAIR</span><h2>${node().depth===7?'보스 전 공통 회복':'회복의 방'}</h2></div><p>호텔 전체 토큰 2개 배분 또는 생존 괴이 하나 강화. <strong>무료 · 한 가지 선택만 적용</strong></p>`;
if(!rd.mode)return body+`<div class="choice-list">${button('회복 · 토큰 총 2개 배분','recovermode:heal','primary',!canHeal)}${!canHeal?'<p class="muted">회복할 손실 토큰이 없습니다.</p>':''}${button('강화 · 생존 괴이 1개','recovermode:upgrade','',!canUpgrade)}${!canUpgrade?'<p class="muted">강화할 미강화 개체가 없습니다.</p>':''}${button('아무것도 하지 않고 떠나기','recoveryskip','ghost')}</div>`;
if(rd.mode==='heal')return body+`<div class="recovery-budget">전체 예산 2 · 배분 ${used} · 남음 ${2-used}</div><p class="muted">검토 중에는 실제 토큰이 바뀌지 않습니다.</p><div class="entity-list">${s.entities.map(e=>{const amount=rd.alloc[e.id]||0,max=def(e).maxP;return `<div class="recovery-entity"><div>${shape(e.type)}<strong>${esc(name(e))}</strong><small>${e.floor?e.floor+'층':'보관 중'} · 개체 ${e.id.replace('e','')}</small><p>현재 ${e.p}/${max} → 회복 후 ${e.p+amount}/${max}</p></div><div>${button('−','healsub:'+e.id,'small',!amount)}<strong>${amount}</strong>${button('+','healadd:'+e.id,'small',used>=2||e.p+amount>=max)}</div></div>`;}).join('')}</div><div class="sticky-actions">${button('선택 취소','recovercancel','ghost')}${button(used?`${used}개 회복${used<2?' · 남은 '+(2-used)+'개 포기':''}`:'배분할 개체를 선택하세요','recoverconfirm','primary',!used)}</div>`;
const selected=entity(rd.entityId),upgraded=selected?{...selected,upgraded:true}:null;return body+`<div class="entity-list">${s.entities.map(e=>`<button class="entity-choice ${rd.entityId===e.id?'selected':''}" data-action="upgradeselect:${e.id}" ${e.upgraded?'disabled':''}>${shape(e.type)}<span><strong>${esc(name(e))}</strong><small>${e.floor?e.floor+'층':'보관 중'} · 개체 ${e.id.replace('e','')} · 토큰 ${e.p}/${def(e).maxP}${e.upgraded?' · 강화 완료':''}</small></span></button>`).join('')}</div>${selected?`<div class="upgrade-compare"><h3>${esc(name(selected))} → ${esc(name(upgraded))}</h3><p>${esc(UPGRADE_TEXT[selected.type])}</p><p>파훼 토큰 ${selected.p}/${def(selected).maxP} 유지 · 공략도 ${selected.c} 유지${def(selected).maxUses?' · 현재 사용 '+selected.uses+'회 유지':''}</p>${effects(upgraded)}</div>`:''}<div class="sticky-actions">${button('선택 취소','recovercancel','ghost')}${button('이 괴이 강화','upgradeconfirm','primary',!selected)}</div>`;}
function diceReward(source='discovery'){const type=source==='event'?node().contents.die:state().phase==='die_reward'?state().reward.die:node().contents.die;return `<div class="panel-heading"><span class="eyebrow">NEW DIE · ONE OFFER</span><h2>${source==='event'?'잊힌 투숙객의 짐':state().phase==='die_reward'?'엘리트 추가 보상':'주사위 발견'}</h2><p>새 주사위 1개 · 무료 교체 · 영혼 증감 없음</p></div><article class="new-die-card"><h3>${DICE[type].name}</h3>${diceFaces(type)}<p>${esc(DICE[type].effectText)}</p></article><h3>현재 장착한 주사위 3개</h3><div class="die-replacements">${state().equipped.map((old,i)=>`<article class="equipment-die ${rewardSlot===i?'selected':''}"><strong>${i+1}. ${DICE[old].name}</strong>${diceFaces(old)}<small>${esc(DICE[old].effectText)}</small>${button(rewardSlot===i?'교체 시 제거':'이 자리 선택','dieslot:'+i,rewardSlot===i?'primary small':'ghost small')}</article>`).join('')}</div>${rewardSlot!=null?`<p class="notice">${rewardSlot+1}번째 ${DICE[state().equipped[rewardSlot]].name} → ${DICE[type].name} · 기존 주사위는 폐기</p>`:''}<div class="sticky-actions">${button(source==='event'?'이벤트 선택으로 돌아가기':'주사위 건너뛰기',source==='event'?'eventback':'dieskip','ghost')}${button('이 주사위로 교체','dieconfirm','primary',rewardSlot==null)}</div>`;}
function eventPanel(){const c=node().contents,s=state();if(eventMode==='die')return diceReward('event');if(eventMode==='contract'){const e=entity(eventTarget);return `<h2>지하 계약 · 제거 대상</h2><p>한 개체를 영구 제거하고 영혼 4를 얻습니다.</p><div class="entity-list">${s.entities.map(x=>`<button class="entity-choice ${x.id===eventTarget?'selected':''}" data-action="eventtarget:${x.id}">${shape(x.type)}<span>${esc(name(x))}<small>${x.floor?x.floor+'층':'보관 중'} · 개체 ${x.id.replace('e','')} · 토큰 ${x.p}/${def(x).maxP}</small></span></button>`).join('')}</div>${e?`<p class="notice danger">${esc(name(e))} · ${e.floor?e.floor+'층':'보관 중'} 영구 제거${e.upgraded?' · 강화도 함께 소멸':''}<br>생존 보유 ${s.entities.length} → ${s.entities.length-1}개 · 영혼 ${s.money} → ${s.money+4}</p>`:''}<div class="sticky-actions">${button('선택 취소','eventback','ghost')}${button('영구 제거하고 영혼 4 획득','eventconfirm','danger',!e||s.entities.length<2)}</div>`;}
const names={luggage:'잊힌 투숙객의 짐',sealed:'봉인된 객실',contract:'지하 계약'};return `<div class="panel-heading"><span class="eyebrow">AN UNEXPECTED VISIT</span><h2>${names[c.event]}</h2></div>${c.event==='luggage'?`<p>주인 없이 남은 가방에서 작은 기계 장치가 발견됐습니다.</p><article class="new-die-card"><h3>${DICE[c.die].name}</h3>${diceFaces(c.die)}<p>${esc(DICE[c.die].effectText)}</p></article><div class="choice-list">${button('주사위 교체 검토','eventdie','primary')}${button('영혼 4 획득 · '+s.money+' → '+(s.money+4),'eventsouls','')}</div>`:c.event==='sealed'?`<p>객실의 봉인을 열면 새 괴이를 얻습니다.</p>${card(c.creature)}<p>영혼 ${s.money} → ${s.money-3} · 미강화 새 개체를 보관함에 추가</p>${button(s.money<3?'영혼 '+(3-s.money)+' 부족':'영혼 3으로 획득','eventbuy','primary',s.money<3)}`:`<p>호텔의 존재 하나를 내어주면 영혼 4를 받습니다. 제거한 괴이와 그 강화는 돌아오지 않습니다.</p>${button('영구 제거 대상 검토','eventcontract','danger',s.entities.length<2)}${s.entities.length<2?'<p>남길 괴이가 최소 1개 필요합니다.</p>':''}`}<div class="sticky-actions">${button('떠나기','leave','ghost')}</div>`;}
function nodePanel(){return state().phase==='management'?preparation():state().phase==='shop'?shop():state().phase==='recovery'?recovery():state().phase==='discovery'?diceReward():state().phase==='event'?eventPanel():'';}
function hotelLayout(onlyHotel=false,readonly=false){return `<main class="hotel-layout preparation-layout"><section class="hotel-column hotel-scene">${state().phase==='management'?guestStrip():`<div class="hotel-heading"><span class="eyebrow">THE HOTEL</span><h2>${state().floorCount}층의 호텔</h2><small>꼭대기 다음은 1층 · 다음 증설 ${game.expansionCost()??'상한'}${game.expansionCost()!=null?'영혼 · 상점에서 구매':''}</small></div>`}<div class="selection-banner ${selection?'':'is-empty'}">${selection?`${selection.kind==='place'?'카드 배치 · 층 또는 보관함 선택':'대상 선택 중'}${button('취소','cancel','small ghost')}`:'전체 층을 한 화면에서 확인하고 배치하세요.'}</div>${hotelFloors(null,readonly)}</section><aside class="decision-column node-column">${onlyHotel?`<section class="node-panel"><h2>호텔 배치와 장착 장비</h2><p>${readonly?'현재는 읽기 전용입니다.':'이동·교환·보관은 무료이며 개체 상태를 유지합니다.'}</p>${equipment()}<p class="muted">파훼 토큰은 회복 노드에서만 회복됩니다.</p></section>`:`<section class="node-panel">${nodePanel()}</section>`}${inventory(readonly)}</aside></main>`;}
function creatureReward(){const s=state();return `<main class="reward-screen"><header><span class="eyebrow">${s.finalVictory?'FINAL VICTORY · LAST DISCOVERY':'ANOMALY DISCOVERED'}</span><h1>${s.finalVictory?'마지막 괴이를 선택하세요':'세 괴이 중 하나를 발견하세요'}</h1><p>${nodeNames[node().kind]} 승리 · 이미 지급한 영혼 합계 +${s.summary?.earned||0} · 보유 영혼 ${s.money}</p><p>${s.finalVictory?'전투 승리 확정 · 최종 보유 목록에 추가한 뒤 승리 결과로 갑니다.':'무료 새 개체 한 개를 보관함에 추가합니다. 기존 개체의 토큰은 바뀌지 않습니다.'}</p></header><div class="reward-grid">${s.reward.creatures.map((type,i)=>card(type,button(rewardIndex===i?'선택 중':'이 괴이 선택','rewardselect:'+i,rewardIndex===i?'primary':'ghost'),rewardIndex===i?'selected':'')).join('')}</div><div class="reward-footer sticky-actions"><span>${rewardIndex==null?'카드를 검토하고 하나를 선택하세요.':def(s.reward.creatures[rewardIndex]).name+' → 보관함 새 개체'}</span>${button('이 괴이 획득','rewardconfirm','primary',rewardIndex==null)}${button('호텔 보기','hotel','ghost')}${button('장비 보기','equipment','ghost')}</div></main>`;}

function previewSummary(p){if(!p)return '';const q=p.summary,loc=q.escaped?`${q.destination}층 탈출 · 전투 노드 종료`:q.killed?`${q.destination||'입장 전'}${q.destination?'층':''} 처치`:p.path.length?`${q.destination}층 도착`:'이동 없음';return `<strong class="preview-summary">${esc(loc)} · 공포 +${q.fear} · 심장 ${q.hearts}개 제거 · ${q.killed?'처치, 반격 없음':q.escaped?'후속 이동·공격 없음':p.attacks.length?'반격 '+p.attacks.length+'회':'반격 없음'}</strong>${q.losses.length?`<p class="danger-text">${q.losses.map(x=>esc(`${x.floor}층 ${x.name} · ${x.destroyed?'파괴':'토큰 '+x.tokens+'개 소모'}`)).join('<br>')}</p>`:''}${q.lost?'<p class="danger-text">이 선택은 패배로 이어집니다.</p>':''}${q.charges?.length?`<p>${q.charges.map(e=>`${e.floor}층 방어 ${e.before} → ${e.after}회`).join(' · ')}</p>`:''}`;}
function previewPanel(p){if(!p)return `<section class="preview-panel route-preview"><p class="muted">주사위를 살펴보면 경로와 결과가 예고됩니다.</p></section>`;const s=state(),virtual=selection&&targetFloor!=null&&validTarget(targetFloor),applied=s.phase==='prepare'&&s.choiceEffect?.requested,virtualEvent=virtual?p.events.find(ev=>['shield','repair'].includes(ev.kind)):null,targetEntity=virtual?at(targetFloor):null;return `<section class="preview-panel route-preview" aria-live="polite">${virtual?`<p class="virtual-label">${targetFloor}층 대상 가상 결과 · 아직 비용 미지불${selection.kind==='G'?'<br>사용 잔량 '+entity(selection.id).uses+' → '+(entity(selection.id).uses-1)+'회':selection.kind==='R'?'<br>불안 '+s.visitor.a+' → '+(s.visitor.a-2)+' · 사용 직후':''}</p>`:''}${virtual?`<p class="target-detail"><strong>${targetEntity?esc(name(targetEntity)):targetFloor+'층 빈층'}</strong><br>${virtualEvent?virtualEvent.kind==='shield'?'이번 턴 보호 '+virtualEvent.before+' → '+virtualEvent.after:'공략도 '+virtualEvent.before+' → '+virtualEvent.after:selection.kind==='escape'?'탈출구 가상 설치 · 접촉 시 종료':''}</p>`:''}${applied?`<p class="completed-effect">✓ 선택 효과 적용 완료 · 실제 불안 +${s.choiceEffect.amount}</p>`:''}${previewSummary(p)}<div class="route-line">${p.events.filter(e=>e.kind==='move').map(e=>`<span class="route-step ${e.arrival?'destination':''}">${e.floor}층 ${e.arrival?'도착':'통과'}</span>`).join(' → ')}</div><details class="preview-detail" ${previewOpen?'open':''}><summary>계산 과정과 개별 공격</summary><ol class="forecast-events">${p.events.map(e=>`<li>${esc(e.text)}</li>`).join('')}</ol><p>최종 공포 ${p.summary.fearAfter} · 불안 ${p.summary.anxietyAfter} · 심장 ${p.summary.heartsAfter}</p></details>${p.uncertainty.length?`<details class="penalty-list" open><summary>별도 무작위 위험 · 공략도 12</summary><p>정상 공격 뒤 생존 괴이 하나. 실제 표적은 아직 미정입니다.</p><ul>${p.uncertainty.map(u=>`<li>${u.floor}층 ${esc(u.name)} · ${u.destroyed?'파괴 가능':'토큰 1개 소모 가능'}${u.defeat?' · 전멸 패배 가능':''}</li>`).join('')}</ul></details>`:''}</section>`;}
function segmented(value,max,forecast,type){const target=forecast??value;return `<div class="segments ${type}" role="img" aria-label="${type==='fear'?'공포':'불안'} ${value}/${max}${target!==value?' · 예상 '+target:''}">${Array.from({length:max},(_,i)=>`<i class="segment ${i<value?'filled':''} ${target>value&&i>=value&&i<target?'forecast':''} ${type==='anxiety'&&target<value&&i>=target&&i<value?'consumed':''} ${(i+1)%5===0?'group-end':''}"></i>`).join('')}</div>`;}
function visitorStatus(p){const s=state(),v=s.visitor;if(!v)return '';const fearForecast=p?p.summary.hearts>0?v.t:Math.min(v.t,v.f+p.summary.fear):v.f,anxietyForecast=p?p.summary.anxietyAfter:v.a;return `<section class="visitor-status ${animationEvent?.kind==='heart'?'heart-event':''}"><div class="visitor-identity"><div class="hearts">${Array.from({length:v.h},(_,i)=>`<span class="heart">♥${p&&i<p.summary.hearts?'<b class="skull" aria-label="제거 예상">☠</b>':''}</span>`).join('')||'<span class="muted">처치</span>'}</div><h2>${esc(v.name)}</h2><small>${nodeNames[node(s)?.kind]||''} · 손님 ${s.guestIndex+1}/${node(s)?.guests.length||1} · ${v.turn}턴</small><button class="text-button" data-action="guest:${s.guestIndex}">공격과 손님 정보</button></div><div class="segmented-bars"><div class="bar-label">공포 <strong>${Math.min(v.f,v.t)} / ${v.t}</strong></div>${segmented(Math.min(v.f,v.t),v.t,fearForecast,'fear')}<div class="bar-label">불안 <strong>${v.a} / 9</strong>${p&&anxietyForecast!==v.a?`<span>예상 ${anxietyForecast}</span>`:''}</div>${segmented(v.a,9,anxietyForecast,'anxiety')}</div></section>`;}
function diceMachine(){const s=state(),selected=s.phase==='prepare'?s.chosenSlot:hoverDie,chosen=selected!=null?s.dice[selected]:null;return `<section class="dice-machine"><div class="machine-nameplate">MECHANICAL DICE ROLLER</div><div class="dice-row ${animationEvent?.kind==='roll'?'rolling':''}">${s.equipped.map((type,i)=>{const d=s.dice[i];return `<button class="die ${selected===i?'selected':''} ${s.phase==='prepare'&&selected!==i?'dimmed':''}" data-action="die:${i}" data-die="${i}" ${s.phase!=='choose'||busy?'disabled':''} aria-pressed="${selected===i}" aria-label="${DICE[type].name}${d?' '+d.value+'칸':''}${d?.bonus?' 선택 시 불안 1 증가':''}"><span class="die-window">${d?d.value:'?'}</span><span class="die-name">${i+1}. ${DICE[type].name}</span><small>${d?d.value+'칸 이동':'아직 굴리지 않음'}</small><span class="die-effect">${d?.bonus?'선택 시 불안 +1':d?'추가 효과 없음':'전체 눈은 장비 정보'}</span></button>`;}).join('')}</div><div class="action-bar">${s.phase==='roll'?button('주사위 굴리기','roll','primary lever'):s.phase==='choose'?button(chosen?`${DICE[chosen.type].name} · ${chosen.value}칸 확정`:'주사위를 검토하세요','choose','primary',hoverDie==null):s.phase==='prepare'?button('이동 실행','move','primary',!!selection):''}</div></section>`;}
function battle(){const p=currentPreview(),s=state();return `<main class="battle-layout"><section class="hotel-column hotel-scene">${visitorStatus(p)}<div class="battle-notice">${busy?esc(animationEvent?.text||'처리 중'):selection?`${selection.kind==='escape'?'출구를 설치할 빈층':selection.kind==='G'?'보호할 괴이':'수리할 괴이'}을 호텔 본체에서 선택하세요.`:s.phase==='prepare'?'노란 테두리의 층을 눌러 직접 사용 · 준비가 끝나면 이동 실행':'주사위를 검토해 이번 경로와 손실을 확인하세요.'}</div>${hotelFloors(p,true)}</section><aside class="elevator-console elevator-panel"><div class="floor-display"><span>CURRENT FLOOR</span><strong>${s.visitor?.pos?String(s.visitor.pos).padStart(2,'0'):'입장 전'}</strong><small>↑ 위로 이동 · ${s.floorCount}층 다음 1층</small></div>${previewPanel(p)}${diceMachine()}<div class="console-actions">${selection?button('대상 선택 취소','cancel','ghost'):s.phase==='prepare'?button('탈출구 설치','escape','ghost',s.escape!=null||s.entities.filter(e=>e.floor).length===s.floorCount):''}${button('장착 주사위 전체 눈','equipment','ghost small')}</div><p class="inactivity-note">비활동 ${s.inactive}턴 · ${s.inactiveLimit-s.inactive}턴 더 이어지면 무작위 공략도 12</p></aside></main>`;}
function result(){const s=state();return `<main class="result-screen"><span class="eyebrow">END OF THE JOURNEY</span><div class="result-emblem">${s.phase==='won'?'✧':'◇'}</div><h1>${s.phase==='won'?'마지막 조사도 끝났습니다':'호텔의 여정이 끝났습니다'}</h1><p>${esc(s.reason)}</p><div class="result-stats">${[['도달 막',s.act+' / 3'],['완료 방문',s.stats.visits+' / 24'],['전투 노드',s.stats.combats],['처치 손님',s.stats.kills],['탈출 손님',s.stats.escaped],['미등장 손님',s.stats.skipped],['영혼 수입',s.stats.earned],['영혼 지출',s.stats.spent],['괴이 파괴',s.stats.destroyed],['계약 제거',s.stats.eventRemoved],['회복 선택',s.stats.recoveries],['회복한 토큰',s.stats.healedTokens],['남긴 회복량',s.stats.recoveryWasted],['강화 개체',s.stats.upgrades],['증설 횟수',s.stats.expansions],['증설 영혼',s.stats.expansionSpent],['호텔 층 수',s.floorCount],['최종 보유 괴이',s.entities.length]].map(([k,v])=>`<div><span>${k}</span><strong>${v??0}</strong></div>`).join('')}</div>${equipment()}<details><summary>최종 보유 괴이와 파훼 토큰</summary><ul>${s.entities.map(e=>`<li>${esc(name(e))} · 개체 ${e.id.replace('e','')} · ${e.floor?e.floor+'층':'보관'} · 토큰 ${e.p}/${def(e).maxP}</li>`).join('')}</ul></details>${seedSelector()}<div class="title-actions">${button('새 판 시작','new','primary')}${button('기록 내려받기','export','ghost')}${button('타이틀','backtitle','ghost')}</div><p class="muted">난수 번호 ${s.seed} · 새 판은 6층·괴이 4개·일반 주사위 3개·영혼 4로 시작합니다.</p></main>`;}
function title(){return `<main class="title-screen"><div class="title-copy"><span class="eyebrow">DREAD TO DEAD · USER 3</span><h1>어서 오세요.<br>어느 길로<br><em>모시겠습니까.</em></h1><p>호텔의 구조를 바꾸고, 괴이를 키우고,<br>세 막에 걸친 밤의 경로를 선택하세요.</p>${seedSelector()}<div class="title-actions">${button('새 모험 시작','new','primary')}${game?button('진행 중인 판으로','resume','ghost'):''}${button('플레이 안내','help','ghost')}</div><div class="title-facts"><span>3막 · 24번의 방문</span><span>6~10층 호텔</span><span>모든 막의 보스 처치</span></div></div><div class="title-art" aria-hidden="true"><div class="hotel-sign">GRAND HOTEL<small>FEARS GO ROUND</small></div>${[6,5,4,3,2,1].map((f,i)=>`<div class="title-floor"><b>${f}</b>${corridorArt(['G','Q','E','Q','B','U'][i],true)}</div>`).join('')}<div class="art-caption">EVERY FLOOR REMEMBERS.</div></div><button class="button ghost title-options" data-action="options">옵션</button></main>`;}
function render(){hideTip();pinned=null;const s=state(),scene=onTitle?'title':`${s.act}:${s.currentNode||'map'}:${combatPhases.includes(s.phase)?'battle':s.phase}`,same=scene===renderedScene;const positions=['.node-panel','.inventory-scroll','.map-scroll'].map(selector=>({selector,top:same?$(selector)?.scrollTop||0:0,left:same?$(selector)?.scrollLeft||0:0})),active=document.activeElement?.dataset?.action,activeFloor=document.activeElement?.dataset?.floor;const view=onTitle?title():s.phase==='map'?mapScreen():combatPhases.includes(s.phase)?battle():s.phase==='anomaly_reward'?creatureReward():s.phase==='die_reward'?`<main class="standalone-panel">${diceReward('elite')}</main>`:['won','lost'].includes(s.phase)?result():hotelLayout();$('#app').innerHTML=(onTitle?'':header())+view;for(const p of positions){const el=$(p.selector);if(el){el.scrollTop=p.top;el.scrollLeft=p.left;}}if(active&&same)$$('[data-action]').find(e=>e.dataset.action===active)?.focus({preventScroll:true});renderedScene=scene;document.body.classList.toggle('resolving',busy);renderModal();if(activeFloor&&same&&!busy&&!modal)surface(`[data-floor="${activeFloor}"]`)?.focus({preventScroll:true});if(!same&&s?.phase==='map')requestAnimationFrame(()=>focusCurrentMap());}
function expansionContent(){const p=game.expansionPreview(expansion),s=state();const side=x=>`<section class="compare-route"><h3>${x.floorCount}층 호텔</h3><p>${x.floorCount}층 → 1층 순환</p><div class="route-line">${x.events.filter(e=>e.kind==='move').map(e=>`${e.floor}층 ${e.arrival?'도착':'통과'}`).join(' → ')}</div><p>마지막 ${x.path.at(-1)}층 · ${esc(x.arrivalEffect)}</p><p>공포 부여 +${x.summary.fear} · 불안 ${expansion.anxiety} → ${x.state.visitor.a}</p><details><summary>선택 효과와 이동 과정</summary><ol>${x.events.map(e=>`<li>${esc(e.text)}</li>`).join('')}</ol></details></section>`;return `<div class="notice"><strong>${s.floorCount} → ${s.floorCount+1}층 · 새 빈층 추가</strong><p>영혼 ${p.cost} 사용 · 잔액 ${p.moneyBefore} → ${p.moneyAfter}</p></div><p>같은 가상 조건의 설계 비교입니다. 실제 미래 눈이나 손님의 공격·심장 판정은 포함하지 않습니다.</p><div class="expand-controls"><label>시작 위치<select data-expand="position">${Array.from({length:s.floorCount+1},(_,i)=>`<option value="${i}" ${expansion.position===i?'selected':''}>${i?i+'층':'입장 전'}</option>`).join('')}</select></label><label>주사위와 면<select data-expand="die">${s.equipped.flatMap((type,slot)=>DICE[type].faces.map((v,face)=>`<option value="${slot},${face}" ${expansion.slot===slot&&expansion.face===face?'selected':''}>${slot+1}. ${DICE[type].name} · ${face+1}면 · ${v}칸${type==='anxiety'&&v===3?' · 불안 +1':''}</option>`)).join('')}</select></label><label>기준 불안<input data-expand="anxiety" type="number" min="0" max="9" value="${expansion.anxiety}"></label><label>기준 공포<input data-expand="fear" type="number" min="0" max="99" value="${expansion.fear}"></label></div><div class="compare-grid">${side(p.before)}${side(p.after)}</div><p>기존 층 번호·괴이 상태는 유지합니다. 구매 후에도 상점에 머무르며 비용은 환급되지 않습니다.</p>${game.expansionReason()?`<p class="danger-text">${esc(game.expansionReason())}</p>`:''}`;}
function renderModal(){if(modal?.type!=='hotel'){hideTip();pinned=null;}$$('.tutorial-highlight').forEach(el=>el.classList.remove('tutorial-highlight'));const root=$('#modal-root');if(!modal){root.innerHTML='';document.body.classList.remove('has-modal');return;}let title='',body='',footer='',wide=false,full=false;const focused=document.activeElement?.dataset?.expand,scroll=$('.modal-body')?.scrollTop||0;if(modal.type==='tutorial'){const anchor={adventure:'.map-panel',souls:'.resource',tokens:'.floor-stats,.hotel-summary',placement:'.inventory-panel',shop:'.shop-grid',recovery:'.node-panel',reward:'.reward-grid',discovery:'.new-die-card',event:'.node-panel',combat:'.segmented-bars',durability:'.floor-stats',inactivity:'.inactivity-note',dice:'.dice-machine',active:'.floor.usable,.elevator-panel',target:'.hotel-board',escape:'.hotel-board',upgrade:'.hotel-summary',final:'.reward-grid'}[modal.key];if(anchor)$(anchor)?.classList.add('tutorial-highlight');[title,body]=tutorial[modal.key];body=`<p>${esc(body)}</p>`;footer=button('앞으로 설명 끄기','tutorialoff','ghost')+button('확인','tutorialnext','primary');}if(modal.type==='help'){title='호텔과 모험 안내';wide=true;body=`<p>지도에서 연결된 다음 노드를 선택합니다. 세 막의 모든 보스를 처치하고 마지막 괴이를 고르면 승리합니다.</p><div class="help-topics">${Object.entries(tutorial).map(([k,[t,body]])=>`<details><summary>${t}</summary><p>${body}</p></details>`).join('')}</div><h3>공통 용어</h3>${Object.entries(glossary).map(([k,t])=>`<details><summary>${k}</summary><p>${t}</p></details>`).join('')}<h3>괴이 사전</h3><div class="card-grid">${Object.keys(CREATURES).map(type=>card(type)).join('')}</div>`;footer=button('닫기','closemodal','primary');}if(modal.type==='options'){title='옵션';body=`<label class="settings-row">첫 등장 안내<input type="checkbox" data-setting="tutorial" ${prefs.tutorial?'checked':''}></label><label class="settings-row">연출 속도<select data-setting="speed"><option value="normal" ${prefs.speed==='normal'?'selected':''}>보통</option><option value="fast" ${prefs.speed==='fast'?'selected':''}>빠름</option></select></label>${seedSelector()}<p>난수 번호는 다음 새 판에 적용합니다. 새로고침하면 현재 판은 초기화됩니다.</p>${button('설명 확인 이력 초기화','resethelp','ghost')}`;footer=button('돌아가기','closemodal','primary');}if(modal.type==='term'){title=modal.key;body=`<p>${esc(glossary[modal.key])}</p>`;footer=button('돌아가기','closeterm','primary');}if(modal.type==='confirm'){title=modal.title;body=modal.html||`<p>${esc(modal.text)}</p>`;footer=button('취소','closemodal','ghost')+button(modal.confirmLabel||'확정',modal.action,modal.danger?'danger':'primary');}if(modal.type==='equipment'){title='장착 주사위';wide=true;body=equipment();footer=button('닫기','closemodal','primary');}if(modal.type==='record'){title='모험 전체 기록';wide=true;body=`<p>난수 번호 ${game.s.seed} · ${game.s.act}막 · ${game.s.stats.visits} / 24 방문 완료</p><ol class="full-record">${game.s.logs.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`;footer=button('기록 내려받기','export','ghost')+button('닫기','closemodal','primary');}if(modal.type==='guest'){title='호텔 초대장';body=guestInvitation(modal.guest,modal.kind);footer=button('닫기','closemodal','primary');}if(modal.type==='card'){title='괴이 정보';body=card(modal.entity||modal.creature);footer=button('닫기','closemodal','primary');}if(modal.type==='floor'){const e=at(modal.floor),p=modal.preview,hits=p?.attacks.filter(x=>x.floor===modal.floor)||[];title=modal.floor+'층 정보';body=(e?card(e):'<p>빈층 · 통과·도착 효과 없음</p>')+(hits.length?'<h3>예상 개별 공격</h3><ol>'+hits.map(hit=>'<li>'+esc(hit.text)+'</li>').join('')+'</ol>':'<p>현재 예고에서 반격 없음</p>');footer=button('닫기','closemodal','primary');}if(modal.type==='map'){title='모험 지도 · 현재 노드를 마쳐야 다음 방문';full=true;body=mapScreen(true);footer=button('현재 화면으로 돌아가기','closemodal','primary');}if(modal.type==='hotel'){title=editable()?'호텔 배치':'호텔 확인 · 읽기 전용';full=true;body=hotelLayout(true,!editable());footer=button('닫기','closemodal','primary');}if(modal.type==='expansion'){title='상점 · 증설 전후 비교';wide=true;body=expansionContent();footer=button('상점으로 돌아가기','closemodal','ghost')+button('증설 확정 · 영혼 '+game.expansionCost(),'expandconfirm','primary',!!game.expansionReason());}
root.innerHTML=`<div class="modal-backdrop ${modal.type==='tutorial'?'guide-backdrop':''}"><section class="modal ${wide?'wide':''} ${full?'full':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><span class="eyebrow">DREAD TO DEAD · USER 3</span><h2>${esc(title)}</h2></div><div class="modal-body">${body}</div><div class="modal-footer">${footer}</div></section></div>`;document.body.classList.add('has-modal');if(focused&&modal.type==='expansion'){root.querySelector(`[data-expand="${focused}"]`)?.focus({preventScroll:true});if($('.modal-body'))$('.modal-body').scrollTop=scroll;}else requestAnimationFrame(()=>root.querySelector('button.primary,button')?.focus({preventScroll:true}));if(modal.type==='map')requestAnimationFrame(focusCurrentMap);}

let animationEnabled=true;
const surface=selector=>modal?.type==='hotel'?$('#modal-root').querySelector(selector)||$(selector):$(selector);
function toast(text){let el=$('.toast');if(!el){el=document.createElement('div');el.className='toast';el.setAttribute('role','status');document.body.append(el);}el.textContent=text;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,4000);}
function showGuestTip(index,box){const g=node()?.guests[index];if(!g||!box)return;showFloatingCard(guestInvitation(g,node().kind),box);}
function showFloatingCard(content,box){const tip=$('#tooltip');tip.classList.add('hover-card');tip.innerHTML=content;tip.hidden=false;tip.style.width=Math.min(330,innerWidth-24)+'px';tip.style.maxHeight=(innerHeight-24)+'px';const r=box.getBoundingClientRect(),w=Math.min(330,innerWidth-24),h=Math.min(tip.offsetHeight,innerHeight-24);tip.style.left=Math.max(12,Math.min(innerWidth-w-12,r.right+10))+'px';tip.style.top=Math.max(12,Math.min(r.top,innerHeight-h-12))+'px';}
function hideTip(){clearTimeout(tipTimer);clearTimeout(tipClose);$('#tooltip').hidden=true;}
function showTip(id,pin=false){const e=entity(id);if(!e)return;const box=surface(e.floor==null?`[data-tooltip-entity="${e.id}"]`:`[data-floor="${e.floor}"]`);if(!box){if(pin){modal={type:'card',entity:copy(e)};renderModal();}return;}pinned=pin?id:null;const p=currentPreview(),events=p?.events.filter(ev=>ev.floor===e.floor&&['move','anxiety','fear','harvest','charge'].includes(ev.kind))||[];let info=events.length?`<div class="card-current"><strong>선택 경로에서 계산</strong><ol>${events.map(ev=>`<li>${esc(ev.text)}</li>`).join('')}</ol></div>`:'';if(selection&&targetFloor===e.floor&&validTarget(e.floor)){info=`<div class="target-forecast"><strong>미확정 대상 · 아직 비용 미지불</strong>${previewSummary(p)}</div>`+info;}
const tip=$('#tooltip');tip.classList.toggle('hover-card',!pin);tip.innerHTML=card(e,info)+(pin?button('정보 닫기','closetip','ghost small'):'');tip.hidden=false;tip.style.width=Math.min(330,innerWidth-24)+'px';tip.style.maxHeight=(innerHeight-24)+'px';const r=box.getBoundingClientRect(),w=Math.min(330,innerWidth-24),h=Math.min(tip.offsetHeight,innerHeight-24);const consoleRect=$('.elevator-panel')?.getBoundingClientRect(),rightLimit=consoleRect?consoleRect.left-12:innerWidth-12;tip.style.left=Math.max(12,Math.min(r.right-w-14,rightLimit-w))+'px';tip.style.top=Math.max(12,Math.min(r.top,innerHeight-h-12))+'px';}
function focusCurrentMap(){const scroll=modal?.type==='map'?$('#modal-root').querySelector('.map-scroll'):$('.map-scroll');if(!scroll)return;const act=mapAct||game.s.act;const depth=act===game.s.act?Math.min(8,game.s.completed[act-1]+1):8;scroll.scrollTop=Math.max(0,75+(8-depth)*110-(scroll.clientHeight||500)*.55);}
function clearTarget(){clearTimeout(targetTimer);targetTimer=null;targetFloor=null;hideTip();}
function cancelSelection(){clearTarget();selection=null;stopDrag();render();}
function beginTarget(e){clearTarget();selection={kind:e.type,id:e.id};render();teach('target');}
function reviewTarget(f){if(!selection||!['G','R','escape'].includes(selection.kind))return;if(!validTarget(f)){leaveTargets();return;}if(targetFloor===f)return;targetFloor=f;hideTip();renderBattlePreview();}
function leaveTargets(){if(!selection||targetFloor==null)return;clearTarget();renderBattlePreview();}
function updateHotelPreview(p){const path=p?.path||[];for(const el of $$('#app .floor[data-floor]')){const f=Number(el.dataset.floor),e=at(f),after=e&&p?.state.entities.find(x=>x.id===e.id),loss=e&&p?e.p-(after?.p||0):0;el.classList.toggle('transit',path.includes(f));el.classList.toggle('arrival',path.at(-1)===f);el.classList.toggle('target-preview',targetFloor===f);el.classList.toggle('danger',loss>0);el.setAttribute('aria-label',`${f}층 ${e?name(e):'빈층'}${selection?validTarget(f)?' · 대상 가능':' · 대상 불가':''}${loss?' · 토큰 '+loss+'개 손실 예상':''}`);const forecast=el.querySelector('.floor-forecast');if(forecast)forecast.textContent=targetFloor===f?'대상 검토 · 아직 미확정':'';const oldThreat=el.querySelector('.floor-threat'),markup=threat(p,e,f);if(oldThreat){if(markup)oldThreat.outerHTML=markup;else oldThreat.remove();}else if(markup)el.insertAdjacentHTML?.('beforeend',markup);}const lane=$('#app .route-lane')||$('.route-lane');if(lane)lane.outerHTML=routeLane(p);}
function renderBattlePreview(){if(!game||busy||!combatPhases.includes(game.s.phase))return;const p=currentPreview(),preview=$('.preview-panel'),status=$('.visitor-status');if(preview)preview.outerHTML=previewPanel(p);if(status)status.outerHTML=visitorStatus(p);updateHotelPreview(p);}
